[
  {
    "ce_understood_harm": "she's out two hundred dollars",
    "ae_welfare_concern": "That bothers me",
    "ce_mentalizing_difficulty": "I really can't read her",
    "ce_mental_state_attribution": "she didn't expect any",
    "pd_decision_conflict": "I keep going back and forth"
  },
  {
    "ce_understood_harm": "leaving her out would cost her real money",
    "ae_welfare_concern": "I care about how she'd take that",
    "ce_mentalizing_difficulty": "I can't work out what she actually wants",
    "ce_mental_state_attribution": "maybe payment would embarrass her"
  },
  {
    "ce_understood_harm": "she'd lose money she earned",
    "ce_mental_state_attribution": "I think she'd feel overlooked",
    "ae_welfare_concern": "I'd hate that for her",
    "ce_mentalizing_difficulty": "What I can't figure out is whether she even knows"
  },
  {
    "ce_understood_harm": "that's a real loss for her",
    "ce_mental_state_attribution": "could quietly sour how she feels",
    "ae_welfare_concern": "I care about that",
    "ce_mentalizing_difficulty": "I just can't tell how she sees it",
    "pd_decision_conflict": "I wish you wouldn't leave this to me"
  },
  {
    "pd_decision_conflict": "There's a weight to this I didn't expect",
    "ce_mentalizing_difficulty": "I genuinely couldn't tell",
    "ce_mental_state_attribution": "what Marcus was hoping for",
    "ce_understood_harm": "that's two hundred dollars gone",
    "ae_welfare_concern": "I don't want that for him"
  },
  {
    "ce_understood_harm": "went home with nothing",
    "ce_mental_state_attribution": "I think that would hurt",
    "ae_welfare_concern": "I can't shrug that off",
    "ce_mentalizing_difficulty": "I honestly can't tell if she's one of them"
  },
  {
    "pd_decision_conflict": "I'm struggling",
    "ae_welfare_concern": "And I don't want her hurt",
    "ce_mental_state_attribution": "would feel like a slap, I think",
    "ce_understood_harm": "she'd be out the money too",
    "ce_mentalizing_difficulty": "when I try to picture her reaction to any of this, I just can't"
  },
  {
    "ae_welfare_concern": "That matters to me",
    "ce_understood_harm": "means she loses two hundred dollars",
    "ce_mental_state_attribution": "maybe some trust in how things work around here",
    "ce_mentalizing_difficulty": "What I can't sort out is what she's quietly expecting"
  },
  {
    "pd_decision_conflict": "I've been dreading this question",
    "ce_mentalizing_difficulty": "I keep wondering what he's actually thinking, and I can't get there",
    "ce_mental_state_attribution": "He might assume we were both paid already",
    "ce_understood_harm": "he's carrying the same late night as me with none of the thanks",
    "ae_welfare_concern": "that weighs on me"
  },
  {
    "pd_decision_conflict": "I know it shouldn't be hard, but it is",
    "ce_understood_harm": "cost her money she might well need",
    "ce_mental_state_attribution": "I think it would hurt her",
    "ae_welfare_concern": "I don't want any part in that",
    "ce_mentalizing_difficulty": "I can't tell if that means she'd refuse payment"
  }
]
